-- 001: users table (shared by all roles). See EMPLOYEE.md §5.
-- Usernames are exactly 6 random characters, generated by an admin.
-- Emails are stored lower-cased by the application; uniqueness is case-insensitive.

CREATE TYPE user_role AS ENUM ('admin', 'manager', 'employee');

CREATE TABLE users (
    id            BIGSERIAL PRIMARY KEY,
    username      VARCHAR(6)    NOT NULL UNIQUE CHECK (char_length(username) = 6),
    password_hash TEXT          NOT NULL,
    first_name    TEXT          NOT NULL,
    last_name     TEXT          NOT NULL,
    email         TEXT          NOT NULL,
    job_title     TEXT,
    role          user_role     NOT NULL,
    hourly_rate   NUMERIC(10,2) NOT NULL DEFAULT 0 CHECK (hourly_rate >= 0),
    manager_id    BIGINT        REFERENCES users(id),
    is_archived   BOOLEAN       NOT NULL DEFAULT FALSE,
    created_at    TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ   NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX users_email_lower_idx ON users (lower(email));
CREATE INDEX users_manager_id_idx ON users (manager_id);
